-- Stable note/journal fields and revision snapshots use typed columns.
-- Malformed or unconvertible legacy values remain in residual data for review.
BEGIN IMMEDIATE;

ALTER TABLE "Note" ADD COLUMN "color" TEXT;
ALTER TABLE "Note" ADD COLUMN "tags" TEXT;
ALTER TABLE "Note" ADD COLUMN "source" TEXT;
ALTER TABLE "Note" ADD COLUMN "date" TEXT;
ALTER TABLE "Note" ADD COLUMN "time" TEXT;
ALTER TABLE "Note" ADD COLUMN "text" TEXT;
ALTER TABLE "Note" ADD COLUMN "prompt" TEXT;
ALTER TABLE "Note" ADD COLUMN "journalVersion" INTEGER;
ALTER TABLE "Note" ADD COLUMN "wordCount" INTEGER;
ALTER TABLE "Note" ADD COLUMN "legacyImportId" TEXT;

UPDATE "Note" SET "color"=json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.color') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.color') IN ('text','null');
UPDATE "Note" SET "data"=json_remove("data", '$.color') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.color') IN ('text','null');
UPDATE "Note" SET "tags"=json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.tags') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.tags')='array' AND json_array_length(CASE WHEN json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.tags')='array' THEN json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.tags') ELSE '[]' END)<=100 AND NOT EXISTS (SELECT 1 FROM json_each(CASE WHEN json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.tags')='array' THEN json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.tags') ELSE '[]' END) label WHERE label.type<>'text' OR length(label.value)>200);
UPDATE "Note" SET "data"=json_remove("data", '$.tags') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.tags')='array' AND json_array_length(CASE WHEN json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.tags')='array' THEN json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.tags') ELSE '[]' END)<=100 AND NOT EXISTS (SELECT 1 FROM json_each(CASE WHEN json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.tags')='array' THEN json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.tags') ELSE '[]' END) label WHERE label.type<>'text' OR length(label.value)>200);
UPDATE "Note" SET "source"=json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.source') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.source') IN ('text','null');
UPDATE "Note" SET "data"=json_remove("data", '$.source') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.source') IN ('text','null');
UPDATE "Note" SET "date"=json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.date') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.date') IN ('text','null');
UPDATE "Note" SET "data"=json_remove("data", '$.date') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.date') IN ('text','null');
UPDATE "Note" SET "time"=json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.time') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.time') IN ('text','null');
UPDATE "Note" SET "data"=json_remove("data", '$.time') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.time') IN ('text','null');
UPDATE "Note" SET "text"=json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.text') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.text') IN ('text','null');
UPDATE "Note" SET "data"=json_remove("data", '$.text') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.text') IN ('text','null');
UPDATE "Note" SET "prompt"=json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.prompt') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.prompt') IN ('text','null');
UPDATE "Note" SET "data"=json_remove("data", '$.prompt') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.prompt') IN ('text','null');
UPDATE "Note" SET "journalVersion"=json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.journalVersion') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.journalVersion')='integer' AND json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.journalVersion') BETWEEN 0 AND 2147483647;
UPDATE "Note" SET "data"=json_remove("data", '$.journalVersion') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.journalVersion')='integer' AND json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.journalVersion') BETWEEN 0 AND 2147483647;
UPDATE "Note" SET "wordCount"=json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.wordCount') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.wordCount')='integer' AND json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.wordCount') BETWEEN 0 AND 2147483647;
UPDATE "Note" SET "data"=json_remove("data", '$.wordCount') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.wordCount')='integer' AND json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.wordCount') BETWEEN 0 AND 2147483647;
UPDATE "Note" SET "legacyImportId"=json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.legacyImportId') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.legacyImportId') IN ('text','null');
UPDATE "Note" SET "data"=json_remove("data", '$.legacyImportId') WHERE json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.legacyImportId') IN ('text','null');
-- Legacy writers can update JSON flags after the older flag-column backfill.
UPDATE "Note" SET "pinned"=json_extract("data", '$.pinned') WHERE CASE WHEN json_valid("data") THEN json_type("data", '$.pinned') IN ('true','false') OR (json_type("data", '$.pinned')='integer' AND json_extract("data", '$.pinned') IN (0,1)) ELSE false END;
UPDATE "Note" SET "starred"=json_extract("data", '$.starred') WHERE CASE WHEN json_valid("data") THEN json_type("data", '$.starred') IN ('true','false') OR (json_type("data", '$.starred')='integer' AND json_extract("data", '$.starred') IN (0,1)) ELSE false END;
UPDATE "Note" SET "data"=json_remove("data", '$.pinned') WHERE (json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.pinned') IN ('true','false') OR (json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.pinned')='integer' AND json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.pinned') IN (0,1)));
UPDATE "Note" SET "data"=json_remove("data", '$.starred') WHERE (json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.starred') IN ('true','false') OR (json_type(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.starred')='integer' AND json_extract(CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END, '$.starred') IN (0,1)));
UPDATE "Note" SET "data"=NULL WHERE "data"='{}';
-- Journals written while the versioned Notes API was disabled must remain private.
UPDATE "Note" SET "kind"='mind-journal' WHERE "source"='mind-journal';

